-- Admin, peña moderation and festival content schema. Run in Supabase SQL Editor.
alter table public.penyes add column if not exists tipo_musica text not null default 'Variada', add column if not exists acepta_visitas boolean not null default false, add column if not exists informacion text not null default '', add column if not exists estado text not null default 'aprobada';
alter table public.penyes drop constraint if exists penyes_estado_check;
alter table public.penyes add constraint penyes_estado_check check (estado in ('pendiente','aprobada','rechazada'));
create table if not exists public.actos(id uuid primary key default gen_random_uuid(),dia date not null,hora text not null default '',titulo text not null,descripcion text not null default '',tipo text not null default 'actuacion' check(tipo in ('actuacion','evento')),lugar text not null default '',publicado boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.eventos(id uuid primary key default gen_random_uuid(),penya_id uuid references public.penyes(id) on delete set null,titulo text not null,descripcion text not null default '',dia date not null,hora text not null default '',lugar text not null default '',publicado boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.site_content(clave text primary key,valor text not null default '',updated_at timestamptz not null default now());
alter table public.penyes enable row level security;alter table public.actos enable row level security;alter table public.eventos enable row level security;alter table public.site_content enable row level security;
do $$ declare p record; begin for p in select policyname from pg_policies where schemaname='public' and tablename='penyes' loop execute format('drop policy if exists %I on public.penyes',p.policyname); end loop; end $$;
create policy "Public can read approved penyes" on public.penyes for select to anon,authenticated using(estado='aprobada' or(auth.jwt()->>'email')='gomezandersonalex@gmail.com');
create policy "Anyone can submit a pending penya" on public.penyes for insert to anon,authenticated with check(estado='pendiente');
create policy "Admin can manage penyes" on public.penyes for all to authenticated using((auth.jwt()->>'email')='gomezandersonalex@gmail.com') with check((auth.jwt()->>'email')='gomezandersonalex@gmail.com');
create policy "Public can read published actos" on public.actos for select to anon,authenticated using(publicado=true or(auth.jwt()->>'email')='gomezandersonalex@gmail.com');
create policy "Admin can manage actos" on public.actos for all to authenticated using((auth.jwt()->>'email')='gomezandersonalex@gmail.com') with check((auth.jwt()->>'email')='gomezandersonalex@gmail.com');
create policy "Public can read published eventos" on public.eventos for select to anon,authenticated using(publicado=true or(auth.jwt()->>'email')='gomezandersonalex@gmail.com');
create policy "Admin can manage eventos" on public.eventos for all to authenticated using((auth.jwt()->>'email')='gomezandersonalex@gmail.com') with check((auth.jwt()->>'email')='gomezandersonalex@gmail.com');
create policy "Public can read site content" on public.site_content for select to anon,authenticated using(true);
create policy "Admin can manage site content" on public.site_content for all to authenticated using((auth.jwt()->>'email')='gomezandersonalex@gmail.com') with check((auth.jwt()->>'email')='gomezandersonalex@gmail.com');
grant select,insert on public.penyes to anon,authenticated;grant update,delete on public.penyes to authenticated;grant select,insert,update,delete on public.actos,public.eventos,public.site_content to anon,authenticated;
insert into public.site_content(clave,valor) values('hero_titulo','Fiestas del Jubileo y del Santísimo Cristo del Buen Acierto'),('hero_subtitulo','L'' ALFÀS DEL PI'),('hero_fechas','Del 07 al 10 de Noviembre de 2026'),('info_titulo','Emergencias'),('info_telefono','112') on conflict(clave) do nothing;